#include <stdio.h>
#include <math.h>
/* ex09：ALOHA / 时隙 ALOHA 的吞吐上限
 * 纯 ALOHA：S = G·e^(-2G)，G=0.5 时最大 S = 1/(2e) ≈ 0.184
 * 时隙 ALOHA：S = G·e^(-G)，G=1 时最大 S = 1/e ≈ 0.368
 * （S = 归一化吞吐，G = 归一化负载）
 * 时隙 ALOHA 把「易冲突窗口」从 2 个帧时减到 1 个，吞吐直接翻倍。*/
int main(void) {
    const double pure_max = 1.0 / (2 * exp(1.0));
    const double slot_max = 1.0 / exp(1.0);

    printf("归一化负载 G -> 归一化吞吐 S\n");
    printf("--------------------------------------------------------------------\n");
    printf("%-6s %-12s %-12s %s\n", "G", "pure-ALOHA", "slotted", "占各自峰值的比例");
    double gs[] = {0.25, 0.5, 1.0, 1.5, 2.0, 3.0};
    for (int i = 0; i < 6; i++) {
        double g = gs[i];
        double pure = g * exp(-2 * g);
        double slot = g * exp(-g);
        printf("%-6.2f %-12.4f %-12.4f pure=%3.0f%% slot=%3.0f%%%s\n",
               g, pure, slot, pure / pure_max * 100, slot / slot_max * 100,
               g == 0.5 ? "  <- 纯 ALOHA 峰值" : (g == 1.0 ? "  <- 时隙 ALOHA 峰值" : ""));
    }
    printf("--------------------------------------------------------------------\n");
    printf("纯 ALOHA 最大值 = 1/(2e) = %.4f (18.4%%)\n", pure_max);
    printf("时隙 ALOHA 最大值 = 1/e  = %.4f (36.8%%)\n", slot_max);
    printf("\n结论：\n");
    printf("  1) ALOHA 类协议最多只能用到带宽的 18.4%% / 36.8%%，效率很低；\n");
    printf("  2) 时隙 ALOHA 的改进只是「把易冲突窗口减半」，吞吐就翻倍 ——\n");
    printf("     这说明 MAC 协议的性能对「冲突窗口大小」极其敏感；\n");
    printf("  3) 纯 ALOHA 的峰值在 G=0.5（负载只有一半就饱和），\n");
    printf("     时隙 ALOHA 的峰值在 G=1.0（能吃满）—— 峰值位置本身就是协议效率的指纹；\n");
    printf("  4) CSMA 进一步要求「先听后发」，把冲突概率降到远低于 ALOHA，\n");
    printf("     再叠加 CSMA/CD（边发边听、冲突即退避），才有了以太网 90%%+ 的利用率。\n");
    return 0;
}
